// Russian dictionary for the dsh-im settings UI in the DSH web GUI.
//
// Keys are the same Chinese literals the settings UI passes to t(), exactly as
// in the EN object of ./i18n.js, and the values are Russian. Product names,
// channel names, commands, config keys, file names, URLs and every template
// placeholder stay untranslated, so a Russian string can be substituted for
// its English counterpart without touching the surrounding code.
//
// The three modules at the end of the import list are shared with the Host half
// of the plugin and are pure data: reusing them keeps the diagnostics and image
// texts worded identically in bot messages and in the settings page. The rest
// of the Host Russian dictionary is deliberately not reused here — it lives in
// modules that carry no strings this UI renders, and a browser bundle should not
// drag them in for a handful of keys. Texts that exist on both sides are
// translated again below; they are short and the two halves may word them
// differently.
//
// This dictionary is an overlay, not a translation of the whole UI: ./i18n.js
// narrows it to the keys the settings UI knows and the locale registry falls
// back to English and then to the Chinese key itself for anything missing.
import diagnostics from '../../src/channels/shared/i18n-ru/diagnostics.mjs';
import imageInput from '../../src/channels/shared/i18n-ru/image-input.mjs';
import weixinDiagnostics from '../../src/channels/shared/i18n-ru/weixin.mjs';

