// Diagnostics, image-input and WeChat connection texts are shared with the Host
// half: the settings UI shows the same messages the bot sends, so they are read
// from the Host Russian modules instead of being written twice. Those modules are
// plain data and are the same ones the English dictionary here already imports.
const SHARED = Object.freeze({
  ...weixinDiagnostics,
  ...diagnostics,
  ...imageInput,
});

// Client wording wins on a key both sides carry: the settings page may need a
// shorter phrasing than a chat message does.
export const RU = Object.freeze({ ...SHARED, ...CLIENT, '$locale': 'ru' });
